// ==========================================================================
// AUTOMATED DOCS REGISTRY
// ==========================================================================
// Central registry for all component documentation metadata
// Automatically discovers and imports all component meta files
// No more manual imports when adding new components!

import { getFolderName, COMPONENT_REGISTRY, createComponentPageImport } from './folderMapping';

// ==========================================================================
// AUTOMATIC META FILE DISCOVERY
// ==========================================================================

/**
 * Automatically discover and import all component meta files
 * This replaces the manual import statements above
 */
const componentMetaFiles = import.meta.glob('../../Pages/Documentation/UiComponents/*/meta.js', { 
  eager: true,
  import: 'default'
});

// Also discover custom-demo components
const customDemoMetaFiles = import.meta.glob('../../custom-demo/*/meta.js', {
  eager: true,
  import: 'default'
});

/**
 * Registry of all component documentation
 * Automatically generated from discovered meta files
 * This array is now completely automated - no manual maintenance needed!
 * 
 * Deduplication: If a component exists in both UiComponents and custom-demo,
 * prefer the UiComponents version (registered/standard version).
 * This prevents duplicate entries when a component is registered.
 */
const uiComponentsDocs = Object.values(componentMetaFiles);
const customDemoDocs = Object.values(customDemoMetaFiles);

// Deduplicate by routeBase: prefer UiComponents over custom-demo
// Create a map using routeBase as the key, UiComponents docs first (they take precedence)
const docsMap = new Map();

// First, add all UiComponents docs (preferred)
uiComponentsDocs.forEach(doc => {
  if (doc && doc.routeBase) {
    docsMap.set(doc.routeBase, doc);
  }
});

// Then, add custom-demo docs only if they don't already exist (by routeBase)
customDemoDocs.forEach(doc => {
  if (doc && doc.routeBase && !docsMap.has(doc.routeBase)) {
    docsMap.set(doc.routeBase, doc);
  }
});

// Convert map values back to array
export const DOCS = Array.from(docsMap.values());

// ==========================================================================
// NAVIGATION GENERATION UTILITIES
// ==========================================================================

/**
 * Generates navigation items from the docs registry
 * This replaces the hardcoded DocNavItems.jsx
 */
export function generateDocNavItems() {
  // Use shared folder name mapping utility

  // Normalize categories to prevent duplicates (case-insensitive grouping)
  // Map lowercase category to canonical form (first occurrence wins)
  const categoryMap = new Map();

  // Group docs by category first, then by subCategory
  const grouped = DOCS.reduce((acc, doc) => {
    // Normalize category: use first occurrence as canonical form
    const categoryLower = doc.category.toLowerCase();
    let canonicalCategory = categoryMap.get(categoryLower);
    
    if (!canonicalCategory) {
      // First time seeing this category (case-insensitive), use it as canonical
      canonicalCategory = doc.category;
      categoryMap.set(categoryLower, canonicalCategory);
    }
    
    // Normalize subCategory similarly
    const subCategoryLower = doc.subCategory.toLowerCase();
    if (!acc[canonicalCategory]) {
      acc[canonicalCategory] = {};
    }
    if (!acc[canonicalCategory][doc.subCategory]) {
      // Check if there's already a subCategory with different case
      const existingSubCategory = Object.keys(acc[canonicalCategory]).find(
        key => key.toLowerCase() === subCategoryLower
      );
      if (existingSubCategory) {
        // Use existing subCategory (canonical form)
        acc[canonicalCategory][existingSubCategory].push(doc);
        return acc;
      }
      acc[canonicalCategory][doc.subCategory] = [];
    }
    acc[canonicalCategory][doc.subCategory].push(doc);
    return acc;
  }, {});

  // Convert to navigation structure
  const navItems = Object.entries(grouped).map(([category, subCategories]) => ({
    menuTitle: category,
    icon: Object.values(subCategories)[0][0].icon, // Use icon from first component
    children: Object.entries(subCategories).map(([subCategory, docs]) => ({
      category: subCategory,
      items: docs.map(doc => {
        return {
          menuItem: doc.menuItem,
          to: doc.routeBase,
          component: createComponentPageImport(doc.menuItem),
          tabs: doc.tabs.map(tab => ({
            name: tab.name,
            to: `${doc.routeBase}${tab.route}`,
            component: tab.component
          }))
        };
      })
    }))
  }));

  // Add Getting Started section
  navItems.unshift({
    menuTitle: 'Getting Started',
    icon: 'pi pi-home',
    to: '/walkthrough' // Simple clickable link - navigates to walkthrough page
  });

  return navItems;
}

/**
 * Gets component metadata by route
 */
export function getComponentMeta(route) {
  return DOCS.find(doc => doc.routeBase === route);
}

/**
 * Gets all routes for routing configuration
 */
export function getAllRoutes() {
  const routes = [];

  // Add Getting Started route
  routes.push({
    path: '/walkthrough',
    element: () => import('../../Pages/Documentation/GettingStarted/Walkthrough')
  });

  // Use shared folder name mapping utility

  DOCS.forEach(doc => {
    // Main component route
    routes.push({
      path: doc.routeBase,
      element: createComponentPageImport(doc.menuItem)
    });
    
    // Tab routes
    doc.tabs.forEach(tab => {
      routes.push({
        path: `${doc.routeBase}${tab.route}`,
        element: tab.component
      });
    });
  });
  
  return routes;
}

// ==========================================================================
// DEBUGGING UTILITIES
// ==========================================================================

/**
 * Debug utility to see what documentation was discovered
 * Use this in development to verify the auto-discovery is working
 */
export function debugDiscoveredDocs() {
  console.log('📚 Auto-discovered documentation:');
  console.log('DOCS array:', DOCS);
  console.log('Total docs found:', DOCS.length);
  
  const groupedByCategory = DOCS.reduce((acc, doc) => {
    if (!acc[doc.category]) {
      acc[doc.category] = [];
    }
    acc[doc.category].push(doc.menuItem);
    return acc;
  }, {});
  
  console.log('Components by category:', groupedByCategory);
  
  return {
    docs: DOCS,
    count: DOCS.length,
    byCategory: groupedByCategory
  };
}
